```java
package com.example.controller;

import com.example.model.Employee;
import org.springframework.stereotype.Controller;
import org.springframework.ui.Model;
import org.springframework.web.bind.annotation.*;
import java.util.ArrayList;
import java.util.List;

@Controller
@RequestMapping("/employees")  // Base URL for all employee operations
public class EmployeeController {

    // In-memory list to store employees (replace with database in production)
    private List<Employee> employees = new ArrayList<>();
    private int nextId = 1;  // Simple ID generator

    // Constructor to initialize sample data
    public EmployeeController() {
        // Add sample employees for demonstration
        addSampleEmployees();
    }

    // Handler for displaying all employees
    @GetMapping
    public String listEmployees(Model model) {
        // Add employees list to the model for view rendering
        model.addAttribute("employees", employees);
        // Return view name - will be resolved to /WEB-INF/views/employees/list.jsp
        return "employees/list";
    }

    // Handler for displaying the add employee form
    @GetMapping("/add")
    public String showAddForm(Model model) {
        // Add empty employee object to model for form binding
        model.addAttribute("employee", new Employee());
        return "employees/addForm";
    }

    // Handler for processing the add employee form submission
    @PostMapping("/add")
    public String addEmployee(@ModelAttribute Employee employee) {
        // Set the next available ID
        employee.setId(nextId++);
        // Add to our list
        employees.add(employee);
        // Redirect to prevent form resubmission
        return "redirect:/employees";
    }

    // Handler for displaying employee details
    @GetMapping("/{id}")
    public String viewEmployee(@PathVariable int id, Model model) {
        // Find employee by ID
        Employee employee = findEmployeeById(id);
        if (employee != null) {
            model.addAttribute("employee", employee);
            return "employees/view";
        }
        return "redirect:/employees";
    }

    // Helper method to find employee by ID
    private Employee findEmployeeById(int id) {
        return employees.stream()
                .filter(emp -> emp.getId() == id)
                .findFirst()
                .orElse(null);
    }

    // Helper method to add sample data
    private void addSampleEmployees() {
        employees.add(new Employee(nextId++, "John Doe", "IT", 75000.0, "john@example.com"));
        employees.add(new Employee(nextId++, "Jane Smith", "HR", 65000.0, "jane@example.com"));
    }
}
```

**Giải thích (VI):** Tạo tầng Controller. Mã ví dụ được giữ nguyên để đối chiếu với bài học.

